public class HelloWorld { // Every Java program lives inside a class. The class name must match the filename exactly, including capitalization. 
    public static void main(String[] args) { // This is the entry point. When Java runs your program, it looks for exactly this method and starts there. Think of it as the front door. 
        System.out.println("Hello, World!"); // This prints a line to the terminal. System is a built-in class. out is its output stream. println prints the text and moves to a new line. 
    }
}